//! Figure for the preliminary gated-fit memo; no rendered source provenance.
use anyhow::Result;use rustplotlib::*;use serde_json::Value;use std::{fs,path::Path};
fn main()->Result<()>{let a:Vec<_>=std::env::args().collect();let f=hdf5::File::open(&a[1])?;let d:Value=serde_json::from_slice(&f.dataset("json_utf8")?.read_raw::<u8>()?)?;let out=Path::new(&a[2]);fs::create_dir_all(out)?;let rows=d["fits"].as_array().unwrap();let mut fig=Figure::new(IntendedUse::ArticleWide);fig.width_mm=180.;fig.height_mm=140.;fig.latex.cache=out.join("latex-cache");
let fields=[("ne",r"$N_e$ (m$^{-3}$)",[1e10,3e13]),("ti_k",r"$T_i$ (K)",[0.,2500.]),("te_k",r"$T_e$ (K)",[0.,12000.]),("velocity_m_s",r"$v_i$ (m/s)",[-1500.,800.]),("h_fraction",r"$f_H$",[0.,1.])];
for(q,(key,label,lim))in fields.iter().enumerate(){let row=q/3;let col=q%3;let rect=Rect::new(19.+col as f64*56.,8.+row as f64*69.,41.,49.);let mut ax=Axes::new(*lim,[100.,1000.],*label,if col==0{"Altitude (km)"}else{""});ax.yticks=vec![100.,400.,700.,1000.];if q==0{ax.set_xscale(AxisScale::Log10)?;ax.xticks=vec![1e10,1e11,1e12,1e13];}if q==2{ax.xticks=vec![0.,4000.,8000.,12000.];}if q==3{ax.xticks=vec![-1500.,-500.,500.];}if q==4{ax.xticks=vec![0.,0.5,1.];}let mut panel=Panel::new(rect,ax);let mut points=vec![];let mut good=vec![];let mut bad=vec![];let mut bounds=vec![];
for r in rows{if q==4&&!r["hydrogen_free"].as_bool().unwrap(){continue;}let z=r["height_km"].as_f64().unwrap();let best=&r["runs"][r["best_run"].as_u64().unwrap()as usize];let n=&best["nodes"][0];let v=if q==0{r["electron_density_m3"].as_f64().unwrap()}else{n[*key].as_f64().unwrap()};let p=[v,z];points.push(p);let flagged=z<200.||n["ti_k"].as_f64().unwrap()<155.||z>990.;if flagged{bad.push(p)}else{good.push(p)}
let j=match q{1=>1,2=>2,3=>3,4=>4,_=>0};let se=best["conditional_standard_error"][j].as_f64();bounds.push(if q==0{[f64::NAN;2]}else if let Some(s)=se{[v-s,v+s]}else{[f64::NAN;2]});}
panel.push(Layer::Line(Line::new(points.clone(),"black")));panel.errorbars(&points,Some(&bounds),None,"black",0.65,2.5,0.6)?;
if !good.is_empty(){panel.markers(&mut fig,&good,&MarkerStyle{shape:MarkerShape::Circle,size_pt:3.5,color:[0.,0.,0.]})?;}if !bad.is_empty(){panel.markers(&mut fig,&bad,&MarkerStyle{shape:MarkerShape::Square,size_pt:4.5,color:[0.,0.,0.]})?;}fig.panels.push(panel);}
fig.save(out.join("preliminary-gated-profile.pdf"))?;fig.save(out.join("preliminary-gated-profile.png"))?;Ok(())}
